// Pools de miner├¡a reales: consulta p├║blica por UID, sin credenciales.
//
// Solo se usan APIs oficiales y p├║blicas de cada pool. Si la pool no responde,
// lo decimos expl├¡citamente (`ok:false`) en vez de inventar hashrate o ganancias:
// mientras un worker est├® entrenando (simulado) se muestra simulaci├│n; cuando se
// conecta a una pool, los n├║meros que se muestran son los reales de esa cuenta.
//
// Monero (XMR) en Nanopool tiene su propio flujo (`fetchMoneroPoolOverview`):
// la pool reparte los datos en varias rutas (`/hashrate`, `/balance`, `/payments`, ÔÇª)
// y su ruta `/user` est├í averiada (devuelve `status:false,"Error"` incluso para
// cuentas activas), por lo que la validaci├│n se apoya en `/accountexist` + `/hashrate`
// + `/balance` y en la validaci├│n local de la direcci├│n Monero.

import { validateMoneroAddress } from "./monero-address";
import { NANOPOOL_LABEL, NANOPOOL_XMR_ENDPOINTS, XMR } from "./nanopool-xmr";

export type PoolId = "hiveon" | "nanopool" | "none";

export type PoolMeta = {
  id: PoolId;
  label: string;
  /** Monedas cubiertas por la API p├║blica. */
  coins: string[];
  /** URL base del endpoint por UID. */
  url: (uid: string, coin: string) => string;
  /** Documentaci├│n p├║blica del endpoint. */
  docs: string;
};

export const MINING_POOLS: Record<Exclude<PoolId, "none">, PoolMeta> = {
  hiveon: {
    id: "hiveon",
    label: "Hiveon Pool (legado ┬À GPU/ASIC)",
    coins: ["ETH", "ETC"],
    url: (uid, coin) =>
      `https://${coin.toLowerCase()}-api.hiveon.com/stats/${encodeURIComponent(uid)}`,
    docs: "https://hiveon.com/",
  },
  nanopool: {
    id: "nanopool",
    label: NANOPOOL_LABEL,
    // Monero es la ├║nica moneda viable en CPU de esta integraci├│n (RandomX).
    coins: [XMR],
    url: (uid) => NANOPOOL_XMR_ENDPOINTS.user(uid),
    docs: "https://xmr.nanopool.org/",
  },
};


export const POOL_IDS = Object.keys(MINING_POOLS) as Exclude<PoolId, "none">[];

/** Normaliza lo que el usuario escribi├│ a un id de pool v├ílido (o "none"). */
export function resolvePoolId(raw: string | null | undefined): PoolId {
  const value = String(raw ?? "").trim().toLowerCase();
  if (!value) return "none";
  if (value.includes("hiveon")) return "hiveon";
  if (value.includes("nano")) return "nanopool";
  return "none";
}

export function poolMeta(raw: string | null | undefined): PoolMeta | null {
  const id = resolvePoolId(raw);
  return id === "none" ? null : MINING_POOLS[id];
}

/** Etiqueta legible para la UI y los logs. */
export function poolLabel(raw: string | null | undefined): string {
  const trimmed = String(raw ?? "").trim();
  return poolMeta(raw)?.label ?? (trimmed || "Sin pool");
}

/**
 * Valida el UID de la pool. Los formatos son alfanum├®ricos; no aceptamos vac├¡os,
 * espacios ni valores con pinta de placeholder.
 */
export function isValidPoolUid(raw: string | null | undefined): boolean {
  const uid = String(raw ?? "").trim();
  if (uid.length < 3 || uid.length > 128) return false;
  if (/\s/.test(uid)) return false;
  if (!/^[A-Za-z0-9._:@+-]+$/.test(uid)) return false;
  return !/^(uid|tu-uid|xxx+|test|ejemplo)$/i.test(uid);
}

/**
 * Valida la wallet de Monero que se usa como UID en Nanopool: formato, longitud,
 * prefijo de red y checksum. Es local (sin red), as├¡ que sirve antes de consultar.
 */
export function validateXmrWallet(raw: string | null | undefined) {
  return validateMoneroAddress(raw);
}

export type PoolStats = {
  ok: boolean;
  pool: string;
  poolLabel: string;
  uid: string;
  coin: string;
  /** Hashrate reportado por la pool, en H/s. */
  hashrate: number;
  /** Media de 24 h si la pool la publica. */
  hashrate24h: number;
  /** Saldo confirmado pendiente de pago. */
  balance: number;
  /** Saldo sin confirmar. */
  unconfirmed: number;
  /** Total pagado hist├│rico. */
  paid: number;
  /** Workers activos seg├║n la pool. */
  workers: number;
  fetchedAt: string;
  error: string | null;
};

function num(value: unknown): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
}

function pick(source: Record<string, unknown>, keys: string[]): unknown {
  for (const key of keys) {
    if (source[key] !== undefined && source[key] !== null) return source[key];
  }
  return undefined;
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

/**
 * Consulta las estad├¡sticas reales de un worker en su pool (API p├║blica por UID).
 * Nunca lanza: si algo falla devuelve `ok:false` con el motivo.
 */
export async function fetchPoolStats(
  pool: string | null | undefined,
  uid: string,
  coin: string,
  timeoutMs = 8000,
): Promise<PoolStats> {
  const meta = poolMeta(pool);
  const base: PoolStats = {
    ok: false,
    pool: meta?.id ?? "none",
    poolLabel: meta?.label ?? "Sin pool",
    uid,
    coin: coin.toUpperCase(),
    hashrate: 0,
    hashrate24h: 0,
    balance: 0,
    unconfirmed: 0,
    paid: 0,
    workers: 0,
    fetchedAt: new Date().toISOString(),
    error: null,
  };

  if (!meta) {
    return { ...base, error: "Pool no soportada: usa Hiveon o Nanopool." };
  }
  if (!isValidPoolUid(uid)) {
    return { ...base, error: "UID de pool inv├ílido." };
  }
  if (!meta.coins.includes(coin.toUpperCase())) {
    return { ...base, error: `${meta.label} no cubre ${coin.toUpperCase()} en su API p├║blica.` };
  }

  // Monero en Nanopool se reparte en varias rutas: ver `fetchMoneroPoolOverview`.
  if (meta.id === "nanopool" && coin.toUpperCase() === XMR) {
    const overview = await fetchMoneroPoolOverview(uid, { timeoutMs });
    return {
      ...base,
      ok: overview.ok,
      hashrate: overview.hashrate,
      hashrate24h: overview.avgHashrate.h24 || overview.hashrate,
      balance: overview.balance,
      unconfirmed: overview.unconfirmed,
      paid: overview.paidTotal,
      workers: overview.workersActive,
      error: overview.error,
    };
  }

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(meta.url(uid, coin.toUpperCase()), {
      signal: ctrl.signal,
      headers: { accept: "application/json" },
    });
    const raw = await res.text();
    if (!res.ok) {
      return { ...base, error: `${meta.label} respondi├│ HTTP ${res.status}.` };
    }
    let payload: Record<string, unknown>;
    try {
      payload = asRecord(JSON.parse(raw));
    } catch {
      return { ...base, error: `${meta.label} devolvi├│ una respuesta ilegible.` };
    }
    const status = pick(payload, ["status"]);
    if (status === false) {
      const message = pick(payload, ["error", "message"]);
      return { ...base, error: String(message ?? "La pool rechaz├│ la consulta.") };
    }
    // Hiveon anida la informaci├│n bajo `stats`; Nanopool bajo `data`.
    const data = { ...asRecord(payload["stats"]), ...asRecord(payload["data"]) };
    const source = Object.keys(data).length ? data : payload;
    const avg = asRecord(pick(source, ["avgHashrate", "hashrate_avg"]));
    const workersRaw = pick(source, ["workers"]);
    const workers = Array.isArray(workersRaw)
      ? workersRaw.length
      : num(pick(source, ["workers_count", "activeWorkers"]));

    const hashrate = num(
      pick(source, ["hashrate", "hashRate", "reportedHashrate", "hashrate_1h"]),
    );
    const hashrate24h =
      num(
        pick(avg, ["h24", "h12", "h6", "h3", "h1"]) ??
          pick(source, ["hashrate_24h", "hashrate24h", "avg_hashrate"]),
      ) || hashrate;

    return {
      ...base,
      ok: true,
      hashrate,
      hashrate24h,
      balance: num(pick(source, ["balance"])),
      unconfirmed: num(pick(source, ["unconfirmed_balance", "unconfirmed"])),
      paid: num(pick(source, ["paid", "total_paid", "payouts_sum"])),
      workers,
    };
  } catch (error) {
    const aborted = error instanceof Error && error.name === "AbortError";
    return {
      ...base,
      error: aborted
        ? `La pool ${meta.label} no respondi├│ a tiempo.`
        : `No se pudo consultar ${meta.label}: ${error instanceof Error ? error.message : "error de red"}`,
    };
  } finally {
    clearTimeout(timer);
  }
}

/* ------------------------- NANOPOOL ┬À MONERO (XMR) ------------------------- */

export type MoneroPayment = {
  /** Hash de la transacci├│n del pago en la red Monero. */
  txHash: string;
  amount: number;
  /** ISO 8601 (la pool devuelve epoch en segundos). */
  date: string;
  confirmed: boolean;
};

export type MoneroHashratePoint = { date: string; hashrate: number };

export type MoneroAvgHashrate = { h1: number; h3: number; h6: number; h12: number; h24: number };

export type MoneroPoolOverview = {
  ok: boolean;
  pool: "nanopool";
  poolLabel: string;
  coin: "XMR";
  wallet: string;
  /** "standard" | "subaddress" | "integrated" cuando la direcci├│n es v├ílida. */
  addressKind: string | null;
  addressValid: boolean;
  addressMessage: string;
  /** La pool conoce la wallet (aunque ahora mismo no reporte hashrate). */
  accountExists: boolean;
  /** Hay un minero reportando ahora mismo. */
  hasActivity: boolean;
  /** Explicaci├│n lista para la UI (estado "sin actividad"). */
  activityNote: string | null;
  hashrate: number;
  avgHashrate: MoneroAvgHashrate;
  /** Saldo confirmado pendiente de pago, en XMR. */
  balance: number;
  unconfirmed: number;
  paidTotal: number;
  paymentsCount: number;
  paidLast24h: number;
  workersActive: number;
  lastShareAt: string | null;
  payments: MoneroPayment[];
  /** ├Ültimas ~24 h de hashrate real (una muestra cada 10 min). */
  history: MoneroHashratePoint[];
  poolHashrate: number | null;
  poolActiveWorkers: number | null;
  /** La ruta `/user` respondi├│ con datos (hoy en XMR devuelve `status:false`). */
  userEndpointWorking: boolean;
  fetchedAt: string;
  error: string | null;
};

type JsonResult = { ok: boolean; payload: Record<string, unknown> | null; error: string | null };

const ZERO_AVG: MoneroAvgHashrate = { h1: 0, h3: 0, h6: 0, h12: 0, h24: 0 };

async function getJson(url: string, timeoutMs: number): Promise<JsonResult> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: ctrl.signal, headers: { accept: "application/json" } });
    const raw = await res.text();
    if (!res.ok) return { ok: false, payload: null, error: `HTTP ${res.status}` };
    return { ok: true, payload: asRecord(JSON.parse(raw) as unknown), error: null };
  } catch (error) {
    return {
      ok: false,
      payload: null,
      error:
        error instanceof Error && error.name === "AbortError" ? "tiempo agotado" : "error de red",
    };
  } finally {
    clearTimeout(timer);
  }
}

/** `data` de una respuesta de Nanopool, solo si `status` no es `false`. */
function nanopoolData(result: JsonResult): unknown {
  if (!result.ok || !result.payload) return undefined;
  if (result.payload["status"] === false) return undefined;
  return result.payload["data"];
}

function epochToIso(value: unknown): string | null {
  const seconds = num(value);
  if (!Number.isFinite(seconds) || seconds <= 0) return null;
  return new Date(seconds * 1000).toISOString();
}

/**
 * Re├║ne las estad├¡sticas reales de una wallet Monero en Nanopool a partir de sus
 * rutas p├║blicas (`/user`, `/hashrate`, `/balance`, `/payments`, medias, workers,
 * hist├│rico y contexto de la pool). Nunca lanza: si la pool no responde devuelve
 * `ok:false`; si responde pero la wallet no tiene minero, `ok:true` + `hasActivity:false`.
 */
export async function fetchMoneroPoolOverview(
  wallet: string,
  options: { timeoutMs?: number; history?: boolean; poolContext?: boolean } = {},
): Promise<MoneroPoolOverview> {
  const timeoutMs = options.timeoutMs ?? 8000;
  const address = validateMoneroAddress(wallet);
  const base: MoneroPoolOverview = {
    ok: false,
    pool: "nanopool",
    poolLabel: NANOPOOL_LABEL,
    coin: "XMR",
    wallet: address.address,
    addressKind: address.ok ? address.kind : null,
    addressValid: address.ok,
    addressMessage: address.message,
    accountExists: false,
    hasActivity: false,
    activityNote: null,
    hashrate: 0,
    avgHashrate: { ...ZERO_AVG },
    balance: 0,
    unconfirmed: 0,
    paidTotal: 0,
    paymentsCount: 0,
    paidLast24h: 0,
    workersActive: 0,
    lastShareAt: null,
    payments: [],
    history: [],
    poolHashrate: null,
    poolActiveWorkers: null,
    userEndpointWorking: false,
    fetchedAt: new Date().toISOString(),
    error: null,
  };

  if (!address.ok) return { ...base, error: address.message };

  const skipped: JsonResult = { ok: false, payload: null, error: "omitido" };
  const [
    account,
    user,
    hashrate,
    balance,
    avg,
    workers,
    payments,
    history,
    poolHashrate,
    poolWorkers,
  ] = await Promise.all([
    getJson(NANOPOOL_XMR_ENDPOINTS.accountExist(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.user(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.hashrate(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.balance(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.avgHashrate(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.workers(address.address), timeoutMs),
    getJson(NANOPOOL_XMR_ENDPOINTS.payments(address.address), timeoutMs),
    options.history === false
      ? Promise.resolve(skipped)
      : getJson(NANOPOOL_XMR_ENDPOINTS.history(address.address), timeoutMs),
    options.poolContext === false
      ? Promise.resolve(skipped)
      : getJson(NANOPOOL_XMR_ENDPOINTS.poolHashrate, timeoutMs),
    options.poolContext === false
      ? Promise.resolve(skipped)
      : getJson(NANOPOOL_XMR_ENDPOINTS.poolActiveWorkers, timeoutMs),
  ]);

  const accountData = nanopoolData(account);
  const hashrateData = nanopoolData(hashrate);
  const balanceData = nanopoolData(balance);
  const userData = asRecord(nanopoolData(user));

  // Si ninguna ruta base respondi├│, el problema es la pool (no la wallet).
  if (!account.ok && !hashrate.ok && !balance.ok) {
    const reason = account.error ?? hashrate.error ?? balance.error ?? "sin respuesta";
    return { ...base, error: `Nanopool no respondi├│ (${reason}). Reintenta en unos minutos.` };
  }

  return buildOverview(base, {
    accountData,
    hashrateData,
    balanceData,
    userData,
    userEndpointWorking: user.payload?.["status"] === true,
    avg: nanopoolData(avg),
    workers: nanopoolData(workers),
    payments: nanopoolData(payments),
    history: nanopoolData(history),
    poolHashrate: nanopoolData(poolHashrate),
    poolWorkers: nanopoolData(poolWorkers),
  });
}

type OverviewInput = {
  accountData: unknown;
  hashrateData: unknown;
  balanceData: unknown;
  userData: Record<string, unknown>;
  userEndpointWorking: boolean;
  avg: unknown;
  workers: unknown;
  payments: unknown;
  history: unknown;
  poolHashrate: unknown;
  poolWorkers: unknown;
};

/** Normaliza la respuesta cruda de Nanopool al contrato que consume la UI. */
function buildOverview(base: MoneroPoolOverview, input: OverviewInput): MoneroPoolOverview {
  const hashrate = num(input.hashrateData);
  const avgData = asRecord(input.avg);
  const avgHashrate: MoneroAvgHashrate = {
    h1: num(avgData["h1"]),
    h3: num(avgData["h3"]),
    h6: num(avgData["h6"]),
    h12: num(avgData["h12"]),
    h24: num(avgData["h24"]),
  };

  const workersList = Array.isArray(input.workers) ? (input.workers as unknown[]) : [];
  const workersActive = workersList.length;
  const lastShareAt =
    workersList
      .map((row) => epochToIso(asRecord(row)["lastShare"]))
      .filter((value): value is string => value !== null)
      .sort()
      .at(-1) ?? null;

  // La pool crea la cuenta en el primer share: `/accountexist` o cualquiera de las
  // rutas de la cuenta contestando con `status:true` significa que la wallet existe.
  const accountExists =
    input.accountData !== undefined ||
    input.hashrateData !== undefined ||
    input.balanceData !== undefined ||
    Object.keys(input.userData).length > 0;

  const hasActivity = hashrate > 0 || workersActive > 0;
  const activityNote = hasActivity
    ? null
    : accountExists
      ? "Sin actividad ÔÇö conecta un minero (XMRig) a esta wallet."
      : "Nanopool todav├¡a no registra esta wallet: aparecer├í en cuanto XMRig env├¡e el primer share.";

  const seen = new Set<string>();
  const payments: MoneroPayment[] = (Array.isArray(input.payments) ? (input.payments as unknown[]) : [])
    .map((row) => {
      const record = asRecord(row);
      return {
        txHash: String(record["txHash"] ?? record["tx_hash"] ?? ""),
        amount: num(record["amount"]),
        date: epochToIso(record["date"]) ?? new Date(0).toISOString(),
        confirmed: record["confirmed"] !== false,
      };
    })
    .filter((payment) => {
      if (payment.amount <= 0 || !payment.txHash || seen.has(payment.txHash)) return false;
      seen.add(payment.txHash);
      return true;
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const dayAgo = Date.now() - 24 * 3600_000;
  const paidTotal = payments.reduce((sum, payment) => sum + payment.amount, 0);
  const paidLast24h = payments
    .filter((payment) => Date.parse(payment.date) >= dayAgo)
    .reduce((sum, payment) => sum + payment.amount, 0);

  const history: MoneroHashratePoint[] = (Array.isArray(input.history) ? (input.history as unknown[]) : [])
    .map((row) => {
      const date = epochToIso(asRecord(row)["date"]);
      return date ? { date, hashrate: num(asRecord(row)["hashrate"]) } : null;
    })
    .filter((point): point is MoneroHashratePoint => point !== null)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-144);

  const poolHashrate = num(input.poolHashrate);
  const poolWorkers = num(input.poolWorkers);

  return {
    ...base,
    ok: true,
    accountExists,
    hasActivity,
    activityNote,
    hashrate,
    avgHashrate,
    balance: num(input.balanceData),
    unconfirmed: num(input.userData["unconfirmed_balance"]),
    paidTotal,
    paymentsCount: payments.length,
    paidLast24h,
    workersActive,
    lastShareAt,
    payments,
    history,
    poolHashrate: poolHashrate > 0 ? poolHashrate : null,
    poolActiveWorkers: poolWorkers > 0 ? poolWorkers : null,
    userEndpointWorking: input.userEndpointWorking,
  };
}

/**
 * Precio XMR/USD p├║blico (Kraken, sin API key) para valorar los pagos en USD.
 * Si falla devuelve `null`: entonces la UI muestra el importe sin conversi├│n.
 */
export async function fetchXmrUsdPrice(timeoutMs = 6000): Promise<number | null> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch("https://api.kraken.com/0/public/Ticker?pair=XMRUSD", {
      signal: ctrl.signal,
      headers: { accept: "application/json" },
    });
    if (!res.ok) return null;
    const payload = asRecord((await res.json()) as unknown);
    const result = asRecord(payload["result"]);
    const ticker = asRecord(Object.values(result)[0]);
    const last = Array.isArray(ticker["c"]) ? num((ticker["c"] as unknown[])[0]) : 0;
    return last > 0 ? last : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// Validaci├│n local de direcciones Monero (XMR). Sin dependencias externas y sin red,
// as├¡ que se puede usar tanto en el navegador (formulario) como en el servidor.
//
// Una direcci├│n Monero son 69 bytes codificados con el base58 propio de Monero:
//   [prefijo de red 1B][clave de gasto 32B][clave de vista 32B][checksum 4B]
// El checksum son los primeros 4 bytes de Keccak-256 (Keccak, NO SHA3-256) del cuerpo.
// Las direcciones integradas (con payment id) ocupan 77 bytes.
//
// Validar aqu├¡ tiene dos ventajas: no se env├¡an direcciones mal escritas a la API
// p├║blica de la pool y se puede distinguir "direcci├│n inv├ílida" de "direcci├│n v├ílida
// pero todav├¡a sin actividad en la pool".

/** Longitudes v├ílidas: 69 bytes -> 95 caracteres, 77 bytes (integrada) -> 106. */
export const MONERO_ADDRESS_LENGTH = { standard: 95, integrated: 106 } as const;

export type MoneroAddressKind = "standard" | "subaddress" | "integrated";

/** Primer byte de la direcci├│n (red principal). Testnet (53/54/63) queda fuera. */
const NETWORK_PREFIXES: Record<number, MoneroAddressKind> = {
  18: "standard",
  19: "integrated",
  42: "subaddress",
};

const ALPHABET = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

/** Bytes que representa un bloque final de N caracteres (bloques completos: 11 -> 8). */
const ENCODED_TO_BYTES: Record<number, number> = {
  2: 1,
  3: 2,
  5: 3,
  6: 4,
  7: 5,
  9: 6,
  10: 7,
  11: 8,
};

/* ------------------------------ Keccak-256 ------------------------------ */

const MASK64 = (1n << 64n) - 1n;

const ROUND_CONSTANTS = [
  0x0000000000000001n, 0x0000000000008082n, 0x800000000000808an, 0x8000000080008000n,
  0x000000000000808bn, 0x0000000080000001n, 0x8000000080008081n, 0x8000000000008009n,
  0x000000000000008an, 0x0000000000000088n, 0x0000000080008009n, 0x000000008000000an,
  0x000000008000808bn, 0x800000000000008bn, 0x8000000000008089n, 0x8000000000008003n,
  0x8000000000008002n, 0x8000000000000080n, 0x000000000000800an, 0x800000008000000an,
  0x8000000080008081n, 0x8000000000008080n, 0x0000000080000001n, 0x8000000080008008n,
];

const ROTATION = [
  1, 3, 6, 10, 15, 21, 28, 36, 45, 55, 2, 14, 27, 41, 56, 8, 25, 43, 62, 18, 39, 61, 20, 44,
];

const PERMUTATION = [
  10, 7, 11, 17, 18, 3, 5, 16, 8, 21, 24, 4, 15, 23, 19, 13, 12, 2, 20, 14, 22, 9, 6, 1,
];

const rotateLeft = (value: bigint, bits: number): bigint =>
  ((value << BigInt(bits)) | (value >> BigInt(64 - bits))) & MASK64;

const lane = (state: bigint[], index: number): bigint => state[index] ?? 0n;

function keccakF(state: bigint[]): void {
  const column = new Array<bigint>(5).fill(0n);
  for (let round = 0; round < 24; round++) {
    for (let i = 0; i < 5; i++) {
      column[i] =
        lane(state, i) ^
        lane(state, i + 5) ^
        lane(state, i + 10) ^
        lane(state, i + 15) ^
        lane(state, i + 20);
    }
    for (let i = 0; i < 5; i++) {
      const theta = lane(column, (i + 4) % 5) ^ rotateLeft(lane(column, (i + 1) % 5), 1);
      for (let j = 0; j < 25; j += 5) {
        state[j + i] = (lane(state, j + i) ^ theta) & MASK64;
      }
    }
    let carry = lane(state, 1);
    for (let i = 0; i < 24; i++) {
      const target = PERMUTATION[i] ?? 0;
      const previous = lane(state, target);
      state[target] = rotateLeft(carry, ROTATION[i] ?? 0);
      carry = previous;
    }
    for (let j = 0; j < 25; j += 5) {
      for (let i = 0; i < 5; i++) column[i] = lane(state, j + i);
      for (let i = 0; i < 5; i++) {
        state[j + i] =
          (lane(state, j + i) ^ (~lane(column, (i + 1) % 5) & MASK64 & lane(column, (i + 2) % 5))) &
          MASK64;
      }
    }
    state[0] = (lane(state, 0) ^ (ROUND_CONSTANTS[round] ?? 0n)) & MASK64;
  }
}

/** Keccak-256 (variante usada por Monero, con padding 0x01). */
export function keccak256(input: Uint8Array): Uint8Array {
  const rate = 136;
  const state = new Array<bigint>(25).fill(0n);
  const total = Math.ceil((input.length + 1) / rate) * rate;
  const padded = new Uint8Array(total);
  padded.set(input);
  padded[input.length] = (padded[input.length] ?? 0) ^ 0x01;
  padded[total - 1] = (padded[total - 1] ?? 0) ^ 0x80;

  for (let offset = 0; offset < total; offset += rate) {
    for (let index = 0; index < rate / 8; index++) {
      let value = 0n;
      for (let byte = 7; byte >= 0; byte--) {
        value = (value << 8n) | BigInt(padded[offset + index * 8 + byte] ?? 0);
      }
      state[index] = (lane(state, index) ^ value) & MASK64;
    }
    keccakF(state);
  }

  const digest = new Uint8Array(32);
  for (let index = 0; index < 4; index++) {
    for (let byte = 0; byte < 8; byte++) {
      digest[index * 8 + byte] = Number((lane(state, index) >> BigInt(byte * 8)) & 0xffn);
    }
  }
  return digest;
}


/* --------------------------- base58 de Monero --------------------------- */

/** Decodifica base58 de Monero (bloques de 11 caracteres -> 8 bytes). `null` si no es v├ílido. */
export function moneroBase58Decode(value: string): Uint8Array | null {
  const bytes: number[] = [];
  let index = 0;

  const decodeChunk = (chunk: string, size: number): number[] | null => {
    let accumulator = 0n;
    for (const char of chunk) {
      const order = ALPHABET.indexOf(char);
      if (order < 0) return null;
      accumulator = accumulator * 58n + BigInt(order);
    }
    if (accumulator >= 1n << BigInt(8 * size)) return null;
    const out: number[] = [];
    for (let byte = size - 1; byte >= 0; byte--) {
      out.push(Number((accumulator >> BigInt(byte * 8)) & 0xffn));
    }
    return out;
  };

  while (value.length - index >= 11) {
    const chunk = decodeChunk(value.slice(index, index + 11), 8);
    if (!chunk) return null;
    bytes.push(...chunk);
    index += 11;
  }

  const rest = value.slice(index);
  if (rest.length > 0) {
    const size = ENCODED_TO_BYTES[rest.length];
    if (!size) return null;
    const chunk = decodeChunk(rest, size);
    if (!chunk) return null;
    bytes.push(...chunk);
  }

  return Uint8Array.from(bytes);
}

/* ------------------------------ Validaci├│n ----------------------------- */

export type MoneroAddressCheck =
  | {
      ok: true;
      address: string;
      kind: MoneroAddressKind;
      length: number;
      prefix: number;
      /** Texto listo para mostrar en la UI. */
      message: string;
    }
  | {
      ok: false;
      address: string;
      length: number;
      reason: string;
      /** Texto listo para mostrar en la UI. */
      message: string;
    };

/**
 * Valida formato, longitud, prefijo de red y checksum de una direcci├│n Monero.
 * Nunca lanza: devuelve `ok:false` con el motivo exacto.
 */
export function validateMoneroAddress(value: string | null | undefined): MoneroAddressCheck {
  const address = String(value ?? "").trim();
  const fail = (reason: string, message: string): MoneroAddressCheck => ({
    ok: false,
    address,
    length: address.length,
    reason,
    message,
  });

  if (!address) return fail("vacia", "Escribe tu direcci├│n de wallet Monero (XMR).");
  if (/\s/.test(address)) {
    return fail("espacios", "La direcci├│n no puede tener espacios ni saltos de l├¡nea.");
  }
  if (
    address.length !== MONERO_ADDRESS_LENGTH.standard &&
    address.length !== MONERO_ADDRESS_LENGTH.integrated
  ) {
    return fail(
      "longitud",
      `Una direcci├│n Monero tiene 95 caracteres (la tuya tiene ${address.length}).`,
    );
  }
  if (!/^[48]/.test(address)) {
    return fail("prefijo", "Debe empezar por 4 (direcci├│n principal) u 8 (subdirecci├│n).");
  }

  const bytes = moneroBase58Decode(address);
  if (!bytes) {
    return fail("base58", "Caracteres no v├ílidos de base58: revisa que la copiaste completa.");
  }
  if (bytes.length !== 69 && bytes.length !== 77) {
    return fail("bytes", `Decodificaci├│n inesperada (${bytes.length} bytes en lugar de 69 o 77).`);
  }

  const prefix = bytes[0] ?? -1;
  const kind = NETWORK_PREFIXES[prefix];
  if (!kind) {
    return fail(
      "red",
      "No es una direcci├│n de la red principal de Monero (las de testnet no sirven en nanopool).",
    );
  }

  const checksum = bytes.slice(bytes.length - 4);
  const expected = keccak256(bytes.slice(0, bytes.length - 4)).slice(0, 4);
  const checksumOk = checksum.every((byte, i) => byte === expected[i]);
  if (!checksumOk) {
    return fail("checksum", "El checksum no cuadra: hay un car├ícter mal copiado en la direcci├│n.");
  }

  return {
    ok: true,
    address,
    kind,
    length: address.length,
    prefix,
    message:
      kind === "subaddress"
        ? "Subdirecci├│n Monero v├ílida (checksum correcto)."
        : kind === "integrated"
          ? "Direcci├│n Monero integrada v├ílida (checksum correcto)."
          : "Direcci├│n Monero v├ílida (checksum correcto).",
  };
}

export function isMoneroAddress(value: string | null | undefined): boolean {
  return validateMoneroAddress(value).ok;
}

/** Etiqueta corta y legible del tipo de direcci├│n. */
export function moneroAddressKindLabel(kind: string | null | undefined): string {
  if (kind === "subaddress") return "subdirecci├│n";
  if (kind === "integrated") return "integrada";
  if (kind === "standard") return "principal";
  return "desconocida";
}

/** Direcci├│n abreviada para la UI: 44AFFqÔÇªBEP3A */
export function shortMoneroAddress(address: string, head = 6, tail = 4): string {
  const value = String(address ?? "").trim();
  if (value.length <= head + tail) return value;
  return `${value.slice(0, head)}ÔÇª${value.slice(-tail)}`;
}

// Nanopool ┬À Monero (XMR): endpoints p├║blicos y datos de conexi├│n del minero.
// M├│dulo sin dependencias de servidor: las URLs se usan desde los server functions
// y las constantes de stratum/comando desde la UI de /mineria.

export const XMR = "XMR";
export const NANOPOOL_ID = "nanopool";
export const NANOPOOL_LABEL = "Nanopool (Monero ┬À CPU)";
export const NANOPOOL_DOCS = "https://xmr.nanopool.org/";

const BASE = "https://api.nanopool.org/v1/xmr";

/**
 * Endpoints p├║blicos de Nanopool para XMR (sin API key).
 * Documentaci├│n: https://xmr.nanopool.org/api
 */
export const NANOPOOL_XMR_ENDPOINTS = {
  /** Datos completos de la cuenta. En XMR esta ruta est├í averiada en la pool. */
  user: (wallet: string) => `${BASE}/user/${encodeURIComponent(wallet)}`,
  /** `status:true` + "Account exist" cuando la pool conoce la wallet. */
  accountExist: (wallet: string) => `${BASE}/accountexist/${encodeURIComponent(wallet)}`,
  /** Hashrate actual en H/s. `status:false` = sin minero reportando. */
  hashrate: (wallet: string) => `${BASE}/hashrate/${encodeURIComponent(wallet)}`,
  /** Saldo confirmado pendiente de pago, en XMR. */
  balance: (wallet: string) => `${BASE}/balance/${encodeURIComponent(wallet)}`,
  /** Historial de pagos reales de la pool. */
  payments: (wallet: string) => `${BASE}/payments/${encodeURIComponent(wallet)}`,
  /** Medias de hashrate (h1, h3, h6, h12, h24) en H/s. */
  avgHashrate: (wallet: string) => `${BASE}/avghashrate/${encodeURIComponent(wallet)}`,
  /** Workers activos de la cuenta. */
  workers: (wallet: string) => `${BASE}/workers/${encodeURIComponent(wallet)}`,
  /** Serie hist├│rica de hashrate (una muestra cada 10 minutos). */
  history: (wallet: string) => `${BASE}/history/${encodeURIComponent(wallet)}`,
  /** Contexto de la pool (hashrate total y workers activos). */
  poolHashrate: `${BASE}/pool/hashrate`,
  poolActiveWorkers: `${BASE}/pool/activeworkers`,
} as const;

/** Endpoints exigidos por el flujo de XMR real (los que consulta el dashboard). */
export const NANOPOOL_XMR_REQUIRED_ENDPOINTS = [
  NANOPOOL_XMR_ENDPOINTS.user,
  NANOPOOL_XMR_ENDPOINTS.hashrate,
  NANOPOOL_XMR_ENDPOINTS.balance,
  NANOPOOL_XMR_ENDPOINTS.payments,
] as const;

/**
 * Stratum de Nanopool para XMR. Hosts y puertos verificados por DNS + conexi├│n TCP;
 * no se inventan servidores que no existan.
 */
export const NANOPOOL_XMR_STRATUM = {
  servers: [
    { region: "Europa", host: "xmr-eu1.nanopool.org" },
    { region: "Europa 2", host: "xmr-eu2.nanopool.org" },
    { region: "EE. UU. este", host: "xmr-us-east1.nanopool.org" },
    { region: "EE. UU. oeste", host: "xmr-us-west1.nanopool.org" },
    { region: "Asia", host: "xmr-asia1.nanopool.org" },
  ],
  /** Puerto stratum est├índar. */
  port: 14444,
  /** Puerto para conexi├│n cifrada (`--tls`). */
  tlsPort: 14433,
  /** Algoritmo de Monero: RandomX, minado por CPU. */
  algorithm: "RandomX (CPU)",
} as const;

/** Nanopool actualiza las estad├¡sticas cada pocos minutos: no refrescamos en tiempo real. */
export const XMR_REFRESH_OPTIONS = [
  { value: 60000, label: "Cada 1 minuto" },
  { value: 120000, label: "Cada 2 minutos" },
  { value: 300000, label: "Cada 5 minutos (recomendado)" },
] as const;

export const XMR_REFRESH_DEFAULT_MS = 300000;
export const XMR_REFRESH_STORAGE_KEY = "dealmaker:xmr-refresh-ms";

/** Comando listo para pegar en PowerShell/CMD con XMRig apuntando a esta wallet. */
export function xmrigCommand(options: {
  wallet: string;
  workerName?: string;
  host?: string;
  port?: number;
  tls?: boolean;
}): string {
  const host = options.host ?? NANOPOOL_XMR_STRATUM.servers[0].host;
  const port = options.port ?? (options.tls ? NANOPOOL_XMR_STRATUM.tlsPort : NANOPOOL_XMR_STRATUM.port);
  const worker = (options.workerName ?? "dealmaker").replace(/\s+/g, "-").slice(0, 32);
  const tls = options.tls ? " --tls" : "";
  return `xmrig.exe -a rx/0 -o ${host}:${port} -u ${options.wallet}.${worker} -p x --donate-level 1${tls}`;
}

