}

function MiningTraining() {
  const qc = useQueryClient();
  const sandboxes = useQuery(miningSandboxesQuery);
  const create = useServerFn(createMiningSandbox);
  const run = useServerFn(runMiningSandbox);
  const promote = useServerFn(promoteMiningRun);
  const [selected, setSelected] = useState<string | null>(null);
  const runs = useQuery(miningRunsQuery(selected));
  const [form, setForm] = useState({
    name: "Sim BTC vs KAS",
    coins: "BTC,KAS",
    pools: "Foundry USA,Kaspa Pool",
    hashRate: "120",
    hashUnit: "TH/s",
    powerCost: "0.12",
    speed: "10",
  });
  const refresh = () => {
    void qc.invalidateQueries({ queryKey: ["mining_sandboxes"] });
    void qc.invalidateQueries({ queryKey: ["mining_training_runs"] });
    void qc.invalidateQueries({ queryKey: ["mining_workers"] });
  };
  const add = async () => {
    try {
      await create({
        data: {
          name: form.name.trim(),
          coins: form.coins.split(",").map((s) => s.trim()).filter(Boolean),
          pools: form.pools.split(",").map((s) => s.trim()).filter(Boolean),
          hashRate: Number(form.hashRate) || 100,
          hashUnit: form.hashUnit.trim() || "TH/s",
          powerCost: Number(form.powerCost) || 0.12,
          dateFrom: new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10),
          dateTo: new Date().toISOString().slice(0, 10),
          speed: Number(form.speed) || 10,
        },
      });
      toast.success("Sandbox de miner├¡a creado");
      refresh();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "No se pudo crear");
    }
  };
  const exec = async (s: MiningSandbox) => {
    try {
      setSelected(s.id);
      await run({ data: { sandboxId: s.id } });
      toast.success("Entrenamiento de miner├¡a completado");
      refresh();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Fall├│ el entrenamiento");
    }
  };
  const pub = async (id: string) => {
    try {
      await promote({ data: { runId: id } });
      toast.success("Mejor combinaci├│n aplicada al worker");
      refresh();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "No se pudo promover");
    }
  };
  return (
    <Card>
      <CardHeader>
        <CardTitle>Campo de entrenamiento ÔÇö miner├¡a (qu├® minar / d├│nde)</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <p className="text-xs text-muted-foreground">
          Laboratorio <b className="text-foreground">simulado</b>: sirve para comparar combinaciones
          moneda/pool antes de decidir. Los workers conectados a una pool real (Nanopool XMR) quedan
          excluidos autom├íticamente, y sus resultados no se pueden aplicar a un worker con wallet
          real hasta desconectarlo. El entrenamiento fija hashrate y ganancias del simulador, no
          datos de la pool.
        </p>
        <div className="grid gap-3 md:grid-cols-4">
          <div className="space-y-1.5"><Label>Nombre</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Monedas (coma)</Label><Input value={form.coins} onChange={(e) => setForm({ ...form, coins: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Pools (coma)</Label><Input value={form.pools} onChange={(e) => setForm({ ...form, pools: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Costo luz USD/kWh</Label><Input value={form.powerCost} onChange={(e) => setForm({ ...form, powerCost: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Potencia (hash rate)</Label><Input value={form.hashRate} onChange={(e) => setForm({ ...form, hashRate: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Unidad</Label><Input value={form.hashUnit} onChange={(e) => setForm({ ...form, hashUnit: e.target.value })} /></div>
          <div className="space-y-1.5"><Label>Velocidad</Label><Input value={form.speed} onChange={(e) => setForm({ ...form, speed: e.target.value })} /></div>
        </div>
        <div className="flex gap-2">
          <Button onClick={add}>Crear sandbox</Button>
        </div>
        {(sandboxes.data ?? []).map((s) => (
          <div key={s.id} className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-border px-3 py-2 text-sm">
            <div>
              <p className="font-medium">{s.name} <span className="text-xs text-muted-foreground">({s.status})</span></p>
              <p className="text-xs text-muted-foreground">{s.coins.join(", ")} ┬À {s.pools.join(", ")}{s.best_coin ? ` ┬À mejor: ${s.best_coin}/${s.best_pool} ${s.estimated_daily_usd} USD/d├¡a` : ""}</p>
              {s.ai_notes && <p className="text-xs text-muted-foreground">{s.ai_notes}</p>}
            </div>
            <div className="flex gap-2">
              <Button size="sm" variant="secondary" onClick={() => exec(s)}>Entrenar</Button>
              <Button size="sm" variant="ghost" onClick={() => setSelected(s.id)}>Ver resultados</Button>
            </div>
          </div>
        ))}
        {selected && (
          <div className="space-y-2">
            {(runs.data ?? []).map((r) => (
              <div key={r.id} className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-border bg-secondary/40 px-3 py-2 text-sm">
                <span><b>{r.worker_name}</b> ┬À {r.coin}/{r.pool} ┬À neto <b className="tabular text-success">{money(Number(r.net_daily_usd), "USD")}</b>/d├¡a (bruto {money(Number(r.gross_daily_usd), "USD")} ÔêÆ luz {money(Number(r.power_daily_usd), "USD")})</span>
                <Button size="sm" variant="secondary" disabled={r.promoted} onClick={() => pub(r.id)}>{r.promoted ? "Aplicado" : "Aplicar al worker"}</Button>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
